    const retired = (c: Claim) => {
      const from = retiredFrom.get(c.personId) ?? null;
      return from !== null && today !== null && today >= from;
    };
    return (c: Claim) => deferred(c, today) || (isOpen(c) && !isBound(c) && retired(c));
